5	#pragma once
6	
7	#include <cute/tensor.hpp>
8	
9	#include "cutlass/fast_math.h"  // For cutlass::FastDivmod
10	
11	#include "utils.h"
12	
13	namespace flash {
14	
15	using namespace cute;
16	
17	template <int kBlockN, int kHeadDim, int kHeadDimV, int NumThreads, typename Element, bool KV_Same_Iter=false, int LoadsPerRow_LB=1>
18	struct PagedKVManager {
19	    // If KV_Same_Iter=false, then we do load_page_table(0), load_K(0), load_page_table(1), load_K(1), load_V(0),
20	    // load_page_table(2), load_K(2), load_V(1), etc.
21	    // So we need to compute the V pointers for the previous iteration.
22	
23	    // LoadsPerRow_LB is the lower bound on number of loads per row in the K direction. This is useful for
24	    // rotary where we want each thread to have at least 2 loads per row.
25	
26	    static constexpr bool SameHeadDim = (kHeadDim == kHeadDimV);
27	    static constexpr int kHeadDimGCD = cute::gcd(kHeadDim, kHeadDimV);
28	
29	    // We use CpAsync for K and V if PagedKV, since TMA doesn't work there
30	    static constexpr int kGmemElemsPerLoad = sizeof(cute::uint128_t) / sizeof(Element);
31	    static_assert(kHeadDimGCD % kGmemElemsPerLoad == 0, "Headdim and HeaddimV must be a multiple of kGmemElemsPerLoad");
32	    // We want each "row" to have 64 elements (128 bytes, i.e. 1 cache line). E.g. if hdim=128, we want each
33	    // thread to have 4 loads in the M direction and 2 vectorized load in the K direction.
34	    // In the case of PackGQA, this reduces the number of times we need to call divmod.
35	    static_assert(kHeadDimGCD % LoadsPerRow_LB == 0, "Headdim and HeaddimV must be a multiple of LoadsPerRow_LB");
36	    static constexpr int kBytePerRow = kHeadDimGCD / LoadsPerRow_LB * sizeof(Element);
37	    static constexpr int kBlockKGmem = (kBytePerRow % 128 == 0 ? 128 : (kBytePerRow % 64 == 0 ? 64 : 32)) / sizeof(Element);
38	    static constexpr int kGmemThreadsPerRow = kBlockKGmem / kGmemElemsPerLoad;
39	    static_assert(NumThreads % kGmemThreadsPerRow == 0, "NumThreads must be a multiple of kGmemThreadsPerRow");
40	    // We assume threads loading the same row are in the same warp. This is for an optimization in PagedKV where
41	    // these threads share the same page table entry and share the work of computing pointers to paged K and paged V.
42	    static_assert(cutlass::NumThreadsPerWarp % kGmemThreadsPerRow == 0, "kGmemThreadsPerRow must divide NumThreadsPerWarp");
43	    using GmemCopyAtomCpAsync = cute::Copy_Atom<SM80_CP_ASYNC_CACHEGLOBAL_ZFILL<uint128_t>, Element>;
44	    using GmemLayoutAtomKVCpAsync = Layout<Shape <Int<NumThreads / kGmemThreadsPerRow>, Int<kGmemThreadsPerRow>>,
45	                                           Stride<Int<kGmemThreadsPerRow>, _1>>;
46	    using GmemTiledCopyKVCpAsync = decltype(
47	        make_tiled_copy(GmemCopyAtomCpAsync{},
48	                        GmemLayoutAtomKVCpAsync{},
49	                        Layout<Shape<_1, Int<kGmemElemsPerLoad>>>{}));  // Val layout, 8 or 16 vals per load
50	    using GmemTiledCopyKVStore = decltype(
51	        make_tiled_copy(Copy_Atom<AutoVectorizingCopyWithAssumedAlignment<128>, Element>{},
52	                        GmemLayoutAtomKVCpAsync{},
53	                        Layout<Shape<_1, Int<kGmemElemsPerLoad>>>{}));  // Val layout, 8 or 16 vals per load
54	
55	    using ShapeKV = cute::Shape<int32_t, int32_t, int32_t, int32_t>;  // (seqlen, d, head, batch)
56	    using StrideKV = cute::Stride<int64_t, _1, int64_t, int64_t>;
57	    using ShapePageTable = cute::Shape<int32_t, int32_t>;  // (batch, max_num_pages_per_seq)
58	    using StridePageTable = cute::Stride<int64_t, _1>;
59	
60	    using TensorPageTable = decltype(make_tensor(make_gmem_ptr(static_cast<int const*>(nullptr)), ShapePageTable{}, StridePageTable{})(int(0), _));
61	    using TensorKV = decltype(make_tensor(make_gmem_ptr(static_cast<Element*>(nullptr)), ShapeKV{}, StrideKV{})(_, _, int(0), _));
62	    using GmemThrCopyKVCpAsync = decltype(GmemTiledCopyKVCpAsync{}.get_thread_slice(int(0)));
63	    using TensortKcK = decltype(GmemTiledCopyKVCpAsync{}.get_thread_slice(int(0)).partition_D(cute::make_identity_tensor(Shape<Int<kBlockN>, Int<kHeadDim>>{})));
64	    using TensortKpK = decltype(make_tensor<bool>(make_shape(size<1>(TensortKcK{}), size<2>(TensortKcK{})), Stride<_0, _1>{}));
65	    using TensortVcV = decltype(GmemTiledCopyKVCpAsync{}.get_thread_slice(int(0)).partition_D(cute::make_identity_tensor(Shape<Int<kBlockN>, Int<kHeadDimV>>{})));
66	    using TensortVpV = decltype(make_tensor<bool>(make_shape(size<1>(TensortVcV{}), size<2>(TensortVcV{})), Stride<_0, _1>{}));
67	
68	    // For PagedKV, it's expensive the calculate the pointers to K and V for each page table entry,
69	    // since those require int64_t arithmetic. We optimize by having threads split this work.
70	    // Typically there are 8 threads loading per row (e.g. hdim 64 and 128), and there are 11 rows
71	    // that each thread needs to load for the case of hdim 128 and kBlockN = 176.
72	    // So each of those 8 threads will calculate the K_ptr and V_ptr for 11 / 8 = 2 rows.
73	    // We then use __shfl_sync to broadcast the pointers to the other threads in the warp.
74	    static_assert(CUTE_STATIC_V(size<1>(TensortKcK{})) == CUTE_STATIC_V(size<1>(TensortVcV{})));
75	    static constexpr int kPageEntryPerThread = cute::ceil_div(size<1>(TensortKcK{}), kGmemThreadsPerRow);
76	    using TensorPageOffset = decltype(make_tensor<cute::tuple<int, int>>(Shape<Int<kPageEntryPerThread>>{}));
77	    using TensorKVPtr = decltype(make_tensor<Element*>(Shape<Int<kPageEntryPerThread>>{}));
78	
79	    GmemTiledCopyKVCpAsync gmem_tiled_copy_kv;
80	    cutlass::FastDivmod const &page_size_divmod;
81	    cutlass::FastDivmod const &blockN_per_page_size_divmod;
82	    int const thread_idx;
83	    int const seqlen_k;
84	    int const leftpad_k;
85	    int const* const ptr_page_table;
86	    GmemThrCopyKVCpAsync const gmem_thr_copy_kv;
87	    TensorPageTable mPageTable;
88	    TensorKV mK_paged, mV_paged;
89	    TensortKpK tKpK;
90	    TensortVpV tVpV;
91	    TensorPageOffset tPrPageOffset;
92	    TensorKVPtr tPrVPtr;
93	    int bidb_kv_idx, bidb_kv_idx_prev, n_block_idx, n_block_idx_prev;  // Only used for TMA
94	
95	    CUTLASS_DEVICE
96	    PagedKVManager(int const* const ptr_page_table_,
97	                   ShapePageTable const &shape_pagetable, StridePageTable const &stride_pagetable,
98	                   Element* const ptr_K, ShapeKV const &shape_K, StrideKV const &stride_K,
99	                   Element* const ptr_V, int const headdim_v, StrideKV const &stride_V,
100	                   cutlass::FastDivmod const &page_size_divmod,
101	                   cutlass::FastDivmod const &blockN_per_page_size_divmod,
102	                   int const bidb, int const bidh, int const thread_idx, int const seqlen_k, int const leftpad_k,
103	                   int bidb_kv_idx
104	                   )
105	        : page_size_divmod(page_size_divmod)
106	        , blockN_per_page_size_divmod(blockN_per_page_size_divmod)
107	        , thread_idx(thread_idx)
108	        , seqlen_k(seqlen_k)
109	        , leftpad_k(leftpad_k)
110	        , ptr_page_table(ptr_page_table_)
111	        , gmem_thr_copy_kv(gmem_tiled_copy_kv.get_thread_slice(thread_idx))
112	        , bidb_kv_idx(bidb_kv_idx)
113	        , bidb_kv_idx_prev(bidb_kv_idx)
114	
115	    {
116	        mPageTable = make_tensor(make_gmem_ptr(ptr_page_table), shape_pagetable, stride_pagetable)(bidb, _);
117	        mK_paged = make_tensor(make_gmem_ptr(ptr_K), shape_K, stride_K)(_, _, bidh, _);
118	        auto shape_V = make_shape(get<0>(shape_K), headdim_v, get<2>(shape_K), get<3>(shape_K));
119	        mV_paged = make_tensor(make_gmem_ptr(ptr_V), shape_V, stride_V)(_, _, bidh, _);
120	        tKpK = make_tensor<bool>(make_shape(size<1>(TensortKcK{}), size<2>(TensortKcK{})), Stride<_0, _1>{});
121	        Tensor cK = cute::make_identity_tensor(Shape<Int<kBlockN>, Int<kHeadDim>>{});  // (BLK_N,BLK_K) -> (blk_n,blk_k)
122	        Tensor tKcK = gmem_thr_copy_kv.partition_S(cK);
123	        #pragma unroll
124	        for (int k = 0; k < size<1>(tKpK); ++k) { tKpK(_0{}, k) = get<1>(tKcK(_0{}, _0{}, k)) < get<1>(shape_K); }
125	        Tensor tVpV_ = make_tensor<bool>(make_shape(size<1>(TensortVcV{}), size<2>(TensortVcV{})), Stride<_0, _1>{});
126	        Tensor cV = cute::make_identity_tensor(Shape<Int<kBlockN>, Int<kHeadDimV>>{});  // (BLK_N,BLK_K) -> (blk_n,blk_k)
127	        Tensor tVcV = gmem_thr_copy_kv.partition_S(cV);
128	        #pragma unroll
129	        for (int k = 0; k < size<1>(tVpV_); ++k) { tVpV_(_0{}, k) = get<1>(tVcV(_0{}, _0{}, k)) < get<1>(shape_V); }
130	        tVpV = cute::conditional_return<SameHeadDim>(tKpK, tVpV_);
131	    };
132	
133	    template <bool Seqlenk_mask=false, bool First_iter=false>
134	    CUTLASS_DEVICE
135	    void load_page_table(const int n_block) {
136	        // The uncoalesced gmem load is intentional. This is so that each thread only loads the page table entries
137	        // it needs, and we don't need any sync between warps.
138	        // Assuming 8 threads per row, and 176 rows, then the rows from 0 to 175 are loaded by
139	        // threads 0, 8, 16, ..., 120, 1, 9, ..., 121, 2, 10, ..., 122, etc.
140	        #pragma unroll
141	        for (int i = 0; i < kPageEntryPerThread; ++i) {
142	            int const row = i * NumThreads + (thread_idx % kGmemThreadsPerRow) * (NumThreads / kGmemThreadsPerRow) + (thread_idx / kGmemThreadsPerRow);
143	            int const row_idx = n_block * kBlockN + row;
144	            int page_idx, page_offset;
145	            page_idx = page_size_divmod.divmod(page_offset, row_idx + leftpad_k);
146	            // Add the condition (i + 1) * NumThreads <= kBlockN since that is an upper bound of row
147	            // and is known at compile time. It avoids branching when e.g., kBlockN = 176 and i = 0.
148	            int const page = ((i + 1) * NumThreads <= kBlockN || row < kBlockN) && (!Seqlenk_mask || row_idx < seqlen_k) ? mPageTable[page_idx] : 0;
149	            tPrPageOffset[i] = {page, page_offset};
150	            // if (cute::thread0()) { printf("row = %d, page_idx = %d, page_offset = %d, page = %d, leftpad_k = %d, seqlen_k = %d\n", row, page_idx, page_offset, page, leftpad_k, seqlen_k); }
151	        }
152	        if constexpr (First_iter && !KV_Same_Iter) { compute_V_ptr(); }
153	    };
154	
155	    template <bool First_iter=false>
156	    CUTLASS_DEVICE
157	    void load_page_table_TMA(const int n_block) {
158	        // We require that page size is a multiple of kBlockN, and there's no leftpad_k
159	        if (ptr_page_table) {
160	            bidb_kv_idx = mPageTable[blockN_per_page_size_divmod.divmod(n_block_idx, n_block)];
161	        } else {
162	            n_block_idx = n_block;
163	        }
164	        if constexpr (First_iter && !KV_Same_Iter) {
165	            bidb_kv_idx_prev = bidb_kv_idx;
166	            n_block_idx_prev = n_block_idx;
167	        }
168	    };
169	
170	    CUTLASS_DEVICE
171	    cute::tuple<int, int> get_indices_for_K_TMA() {
172	        return {n_block_idx, bidb_kv_idx};
173	    };
174	
175	    CUTLASS_DEVICE
176	    cute::tuple<int, int> get_indices_for_V_TMA() {
177	        if constexpr (KV_Same_Iter) {
178	            return {n_block_idx, bidb_kv_idx};
179	        } else {
180	            cute::tuple<int, int> const indices = {n_block_idx_prev, bidb_kv_idx_prev};
181	            bidb_kv_idx_prev = bidb_kv_idx;
182	            n_block_idx_prev = n_block_idx;
183	            return indices;
184	        }
185	    };
186	
187	    CUTLASS_DEVICE
188	    TensorKVPtr compute_K_ptr() {
189	        Tensor tPrKPtr = make_tensor<Element*>(Shape<Int<kPageEntryPerThread>>{});
190	        #pragma unroll
191	        for (int i = 0; i < kPageEntryPerThread; ++i) {
192	            auto [page, page_offset] = tPrPageOffset[i];
193	            tPrKPtr[i] = &mK_paged(page_offset, _0{}, page);
194	        }
195	        return tPrKPtr;
196	    };
197	
198	    CUTLASS_DEVICE
199	    void compute_V_ptr() {
200	        #pragma unroll
201	        for (int i = 0; i < kPageEntryPerThread; ++i) {
202	            auto [page, page_offset] = tPrPageOffset[i];
203	            tPrVPtr[i] = &mV_paged(page_offset, _0{}, page);
204	        }
205	    };
206	
207	    template <bool Seqlenk_mask=false, typename TensorK>
208	    CUTLASS_DEVICE
209	    void load_K(const int n_block, TensorK &&sK) {
210	        // Do we need bound check to make sure the row doesn't go above kBlockN
211	        static constexpr bool EvenN = kBlockN % CUTE_STATIC_V(shape<0>(GmemLayoutAtomKVCpAsync{})) == 0;
212	
213	        Tensor tPrKPtr = compute_K_ptr();
214	
215	        // Only for index calculation, since all the indices of thread 0 are known at compile time
216	        auto gmem_thr0_copy_kv = gmem_tiled_copy_kv.get_thread_slice(_0{});
217	        Tensor tKsK = gmem_thr_copy_kv.partition_D(sK);
218	        Tensor cK = cute::make_identity_tensor(Shape<Int<kBlockN>, Int<kHeadDim>>{});  // (BLK_N,BLK_K) -> (blk_n,blk_k)
219	        // Repeat the partitioning with identity layouts
220	        Tensor tKcK = gmem_thr_copy_kv.partition_S(cK);
221	        Tensor t0KcK = gmem_thr0_copy_kv.partition_S(cK);
222	
223	        // We want to use the row indices of thread0 to compare, since that is known at compile time.
224	        // So we subtract the limit by the first row index of this thread (get<0>(tKcK(_0{}, _0{}, _0{})))
225	        int const seqlenk_row_limit = -int(get<0>(tKcK(_0{}, _0{}, _0{}))) + (EvenN
226	            ? seqlen_k - n_block * kBlockN
227	            : (!Seqlenk_mask ? kBlockN : std::min(seqlen_k - n_block * kBlockN, kBlockN)));
228	        #pragma unroll
229	        for (int m = 0; m < size<1>(tKsK); ++m) {
230	            bool const should_load = EvenN
231	                ? (!Seqlenk_mask || get<0>(t0KcK(_0{}, m, _0{})) < seqlenk_row_limit)
232	                : get<0>(t0KcK(_0{}, m, _0{})) < seqlenk_row_limit;
233	            Element const* k_ptr = reinterpret_cast<Element const*>(__shfl_sync(0xffffffff, reinterpret_cast<uint64_t>(tPrKPtr(m / kGmemThreadsPerRow)), (m % kGmemThreadsPerRow), kGmemThreadsPerRow));
234	            Tensor mK_paged_cur = make_tensor(make_gmem_ptr(k_ptr), Shape<Int<kHeadDim>>{});
235	            Tensor mK_paged_cur_copy = cute::tiled_divide(mK_paged_cur, Shape<Int<kGmemElemsPerLoad>>{});
236	            if (should_load) {
237	                #pragma unroll
238	                for (int k = 0; k < size<2>(tKsK); ++k) {
239	                    int const ki = get<1>(tKcK(_0{}, _0{}, k)) / kGmemElemsPerLoad;
240	                    cute::copy(gmem_tiled_copy_kv.with(tKpK(_0{}, k)), mK_paged_cur_copy(_, ki), tKsK(_, m, k));
241	                }
242	            }  // Don't need to clear out the rest of the smem since we'll mask out the scores anyway
243	        }
244	    };
245	
246	    template <bool Seqlenk_mask=false, typename TensorV>
247	    CUTLASS_DEVICE
248	    void load_V(const int n_block, TensorV &&sV) {
249	        // Do we need bound check to make sure the row doesn't go above kBlockN
250	        static constexpr bool EvenN = kBlockN % CUTE_STATIC_V(shape<0>(GmemLayoutAtomKVCpAsync{})) == 0;
251	
252	        if constexpr (KV_Same_Iter) { compute_V_ptr(); }
253	        // Only for index calculation, since all the indices of thread 0 are known at compile time
254	        auto gmem_thr0_copy_kv = gmem_tiled_copy_kv.get_thread_slice(_0{});
255	        Tensor tVsV = gmem_thr_copy_kv.partition_D(sV);
256	        Tensor cV = cute::make_identity_tensor(Shape<Int<kBlockN>, Int<kHeadDimV>>{});  // (BLK_N,BLK_K) -> (blk_n,blk_k)
257	        // Repeat the partitioning with identity layouts
258	        Tensor tVcV = gmem_thr_copy_kv.partition_S(cV);
259	        Tensor t0VcV = gmem_thr0_copy_kv.partition_S(cV);
260	
261	        int const seqlenk_row_limit = seqlen_k - n_block * kBlockN - get<0>(tVcV(_0{}, _0{}, _0{}));
262	        #pragma unroll
263	        for (int m = 0; m < size<1>(tVsV); ++m) {
264	            // Faster to rely on the cp.async to clear smem that are out of bound,
265	            // rather than calling cute::clear directly.
266	            // We have to be careful not to write to smem past `kBlockN` if !EvenN.
267	            // If kBlockN doesn't evenly divide the tiled copy, only the last `m` needs to checked
268	            if (EvenN || m < size<1>(tVsV) - 1 || get<0>(tVcV(_0{}, m, _0{})) < kBlockN) {
269	                bool const should_load = !Seqlenk_mask || get<0>(t0VcV(_0{}, m, _0{})) < seqlenk_row_limit;
270	                Element const* v_ptr = reinterpret_cast<Element const*>(__shfl_sync(0xffffffff, reinterpret_cast<uint64_t>(tPrVPtr(m / kGmemThreadsPerRow)), m % kGmemThreadsPerRow, kGmemThreadsPerRow));
271	                Tensor mV_paged_cur = make_tensor(make_gmem_ptr(v_ptr), Shape<Int<kHeadDimV>>{});
272	                Tensor mV_paged_cur_copy = cute::tiled_divide(mV_paged_cur, Shape<Int<kGmemElemsPerLoad>>{});
273	                #pragma unroll
274	                for (int k = 0; k < size<2>(tVsV); ++k) {
275	                    int const ki = get<1>(tVcV(_0{}, _0{}, k)) / kGmemElemsPerLoad;
276	                    cute::copy(gmem_tiled_copy_kv.with(tVpV(_0{}, k) && should_load), mV_paged_cur_copy(_, ki), tVsV(_, m, k));
277	                }
278	            }
279	        }
280	        if constexpr (!KV_Same_Iter) { compute_V_ptr(); }
281	    };
282	
283	    template <typename TensorK>
284	    CUTLASS_DEVICE
285	    void store_K(const int n_block, TensorK &&tKrK) {
286	        Tensor tPrKPtr = compute_K_ptr();
287	        // We're using the same partitioning as GmemTiledCopyKVCpAsync (used for loading)
288	        // Only for index calculation, since all the indices of thread 0 are known at compile time
289	        auto gmem_thr0_copy_kv = gmem_tiled_copy_kv.get_thread_slice(_0{});
290	        Tensor cK = cute::make_identity_tensor(Shape<Int<kBlockN>, Int<kHeadDim>>{});  // (BLK_N,BLK_K) -> (blk_n,blk_k)
291	        // Repeat the partitioning with identity layouts
292	        Tensor tKcK = gmem_thr_copy_kv.partition_S(cK);
293	        Tensor t0KcK = gmem_thr0_copy_kv.partition_S(cK);
294	
295	        GmemTiledCopyKVStore gmem_tiled_copy_kv_store;
296	        // We want to use the row indices of thread0 to compare, since that is known at compile time.
297	        // So we subtract the limit by the first row index of this thread (get<0>(tKcK(_0{}, _0{}, _0{})))
298	        // int const seqlenk_row_limit = seqlen_k - n_block * kBlockN - get<0>(tKcK(_0{}, _0{}, _0{}));
299	        int const seqlenk_row_limit = std::min(seqlen_k - n_block * kBlockN, kBlockN) - get<0>(tKcK(_0{}, _0{}, _0{}));
300	        // if (threadIdx.x == 128) { printf("bidx = %d, bidy = %d, bidz = %d, seqlen_k = %d, seqlenk_row_limit = %d\n", blockIdx.x, blockIdx.y, blockIdx.z, seqlen_k, seqlenk_row_limit); }
301	        #pragma unroll
302	        for (int m = 0; m < size<1>(tKrK); ++m) {
303	            bool const should_load = get<0>(t0KcK(_0{}, m, _0{})) < seqlenk_row_limit;
304	            Element* k_ptr = reinterpret_cast<Element*>(__shfl_sync(0xffffffff, reinterpret_cast<uint64_t>(tPrKPtr(m / kGmemThreadsPerRow)), (m % kGmemThreadsPerRow), kGmemThreadsPerRow));
305	            Tensor mK_paged_cur = make_tensor(make_gmem_ptr(k_ptr), Shape<Int<kHeadDim>>{});
306	            Tensor mK_paged_cur_copy = cute::tiled_divide(mK_paged_cur, Shape<Int<kGmemElemsPerLoad>>{});
307	            if (should_load) {
308	                #pragma unroll
309	                for (int k = 0; k < size<2>(tKrK); ++k) {
310	                    int const ki = get<1>(tKcK(_0{}, _0{}, k)) / kGmemElemsPerLoad;
311	                    if (tKpK(_0{}, k)) {
312	                        cute::copy(gmem_tiled_copy_kv_store, tKrK(_, m, k), mK_paged_cur_copy(_, ki));
313	                    }
314	                }
315	            }
316	        }
317	    };
318	
319	    template <typename TensorV>
320	    CUTLASS_DEVICE
321	    void store_V(const int n_block, TensorV &&tVrV) {
322	        if constexpr (KV_Same_Iter) { compute_V_ptr(); }
323	        // Only for index calculation, since all the indices of thread 0 are known at compile time
324	        auto gmem_thr0_copy_kv = gmem_tiled_copy_kv.get_thread_slice(_0{});
325	        Tensor cV = cute::make_identity_tensor(Shape<Int<kBlockN>, Int<kHeadDimV>>{});  // (BLK_N,BLK_K) -> (blk_n,blk_k)
326	        // Repeat the partitioning with identity layouts
327	        Tensor tVcV = gmem_thr_copy_kv.partition_S(cV);
328	        Tensor t0VcV = gmem_thr0_copy_kv.partition_S(cV);
329	
330	        GmemTiledCopyKVStore gmem_tiled_copy_kv_store;
331	        int const seqlenk_row_limit = std::min(seqlen_k - n_block * kBlockN, kBlockN) - get<0>(tVcV(_0{}, _0{}, _0{}));
332	        #pragma unroll
333	        for (int m = 0; m < size<1>(tVrV); ++m) {
334	            bool const should_load = get<0>(t0VcV(_0{}, m, _0{})) < seqlenk_row_limit;
335	            Element* v_ptr = reinterpret_cast<Element*>(__shfl_sync(0xffffffff, reinterpret_cast<uint64_t>(tPrVPtr(m / kGmemThreadsPerRow)), m % kGmemThreadsPerRow, kGmemThreadsPerRow));
336	            Tensor mV_paged_cur = make_tensor(make_gmem_ptr(v_ptr), Shape<Int<kHeadDimV>>{});
337	            Tensor mV_paged_cur_copy = cute::tiled_divide(mV_paged_cur, Shape<Int<kGmemElemsPerLoad>>{});
338	            if (should_load) {
339	                #pragma unroll
340	                for (int k = 0; k < size<2>(tVrV); ++k) {
341	                    int const ki = get<1>(tVcV(_0{}, _0{}, k)) / kGmemElemsPerLoad;
342	                    if (tVpV(_0{}, k)) {
343	                        cute::copy(gmem_tiled_copy_kv_store, tVrV(_, m, k), mV_paged_cur_copy(_, ki));
344	                    }
345	                }
346	            }
347	        }
348	        if constexpr (!KV_Same_Iter) { compute_V_ptr(); }
349	    };
350	
351	
352	};
353	
354	} // namespace flash
