33	        bool MmaPV_is_RS, bool IntraWGOverlap, bool PackGQA_, bool Split_, bool V_colmajor_, class ElementSAux_, int kBlockH_=1>
34	struct CollectiveMainloopFwdSm90 {
35	
36	    static constexpr int kStages = Stages;
37	    using ClusterShape = ClusterShape_;
38	    using TileShape_MNK = TileShape_MNK_;
39	    using TileShape_MNK_PV = Shape<decltype(get<0>(TileShape_MNK{})), Int<kHeadDimV>, decltype(get<1>(TileShape_MNK{}))>;
40	    using TileShape_MNK_QV = Shape<decltype(get<0>(TileShape_MNK{})), decltype(get<1>(TileShape_MNK{})), Int<kHeadDimV>>;
41	    using Element = Element_;
42	    using ElementAccum = ElementAccum_;
43	    using ElementSAux = ElementSAux_;
44	    using ArchTag = ArchTag_;
45	    static constexpr bool Is_FP8 = cute::is_same_v<Element, cutlass::float_e4m3_t> || cute::is_same_v<Element, cutlass::float_e5m2_t>;;
46	    static constexpr bool Is_causal = Is_causal_;
47	    static constexpr bool Is_local = Is_local_;
48	    static constexpr bool Has_softcap = Has_softcap_;
49	    static constexpr bool Varlen = Varlen_;
50	    static constexpr bool PagedKVNonTMA = PagedKVNonTMA_;
51	    static constexpr bool AppendKV = AppendKV_;
52	    static constexpr bool HasQv = HasQv_;
53	    static constexpr bool PackGQA = PackGQA_;
54	    static constexpr bool PackGQA_TMA = PackGQA && kBlockH_ > 1;
55	    static constexpr bool Split = Split_;
56	    static constexpr bool V_colmajor = V_colmajor_;
57	    static constexpr bool Transpose_V = Is_FP8 && !V_colmajor;
58	    static constexpr bool Use_TMA_Q = !PackGQA || PackGQA_TMA;
59	    static constexpr bool Use_TMA_KV = !PagedKVNonTMA;
60	    static_assert(Use_TMA_KV || CUTE_STATIC_V(size(ClusterShape{})) == 1, "If not using TMA for KV, ClusterShape must be 1");
61	    static_assert(Use_TMA_KV || !V_colmajor, "If not using TMA for KV, V_colmajor is not supported");
62	    static constexpr bool SameHeadDim = get<2>(TileShape_MNK{}) == kHeadDimV;
63	    static constexpr bool LargeHeadDimV = kHeadDimV > 256;
64	
65	    static_assert(ArchTag::kMinComputeCapability >= 90);
66	
67	    static constexpr cute::GMMA::Major MmaMajorV = !Is_FP8 && !V_colmajor ? GMMA::Major::MN : GMMA::Major::K;
68	    static constexpr cute::GMMA::Major TmaMajorV = !V_colmajor ? GMMA::Major::MN : GMMA::Major::K;
69	
70	    static constexpr int kBlockM = get<0>(TileShape_MNK{});
71	    static constexpr int kBlockN = get<1>(TileShape_MNK{});
72	    static constexpr int kHeadDim = get<2>(TileShape_MNK{});
73	    static constexpr int kBlockH = kBlockH_;
74	
75	    using SeqlenInfo_t = flash::SeqlenInfoQKNewK<Varlen, AppendKV>;
76	    using BlockMN_t = flash::BlockMN<SeqlenInfo_t, kBlockM, kBlockN, Is_causal, Is_local, PackGQA, Split>;
77	
78	    static_assert(!LargeHeadDimV || kHeadDimV % 256 == 0);
79	    static_assert(!LargeHeadDimV || kBlockM <= 64, "kBlockM must be 64 or less for large Headdim_V");
80	    static_assert(!LargeHeadDimV || !MmaPV_is_RS, "MmaPV must be SS for large Headdim_V");
81	
82	    // Register bandwidth is actually a bottleneck so we don't want Q to be in registers.
83	    // Leaving this option here for reference.
84	    static constexpr bool MmaQK_is_RS = false;
85	    // We can have MmaPV with P in smem in rmem to reduce register pressure at the cost of more smem.
86	    static_assert(!(!MmaPV_is_RS && Is_FP8), "MmaPV must be RS if FP8");
87	    static_assert(!(!MmaPV_is_RS && Transpose_V), "MmaPV must be RS if Transpose_V");
88	
89	    // Slightly faster in this case to have WG1 use RS instead of SS to avoid waiting for the P smem write
90	    static constexpr bool MmaPV_use_RS_WG1 = !MmaPV_is_RS && kHeadDim == 64 && kHeadDimV == 512;
91	
92	    using AtomLayoutQK = Layout<Shape<Int<kBlockM / 64>, _1, _1>>;
93	    using TiledMmaQK = decltype(cute::make_tiled_mma(
94	        std::conditional_t<
95	            !MmaQK_is_RS,
96	            decltype(cute::GMMA::ss_op_selector<Element, Element, ElementAccum, TileShape_MNK>()),
97	            decltype(cute::GMMA::rs_op_selector<Element, Element, ElementAccum, TileShape_MNK>())
98	        >{},
99	        AtomLayoutQK{}));
100	    using AtomLayoutPV = std::conditional_t<
101	        !LargeHeadDimV,
102	        AtomLayoutQK,
103	        Layout<Shape<_1, Int<kHeadDimV / 256>, _1>>
104	    >;
105	    using TiledMmaPV = decltype(cute::make_tiled_mma(
106	        std::conditional_t<
107	            !MmaPV_is_RS,
108	            decltype(cute::GMMA::ss_op_selector<Element, Element, ElementAccum,
109	                     TileShape_MNK_PV, GMMA::Major::K, MmaMajorV>()),
110	            decltype(cute::GMMA::rs_op_selector<Element, Element, ElementAccum,
111	                     TileShape_MNK_PV, GMMA::Major::K, MmaMajorV>())
112	        >{},
113	        AtomLayoutPV{}));
114	    using TiledMmaQV = decltype(cute::make_tiled_mma(
115	        cute::GMMA::ss_op_selector<Element, Element, ElementAccum, TileShape_MNK_QV>(),
116	        AtomLayoutQK{}));
117	    // For hdim64,512, WG1 can use RS but WG2 must use SS
118	    using TiledMmaPV_RS = decltype(cute::make_tiled_mma(
119	        cute::GMMA::rs_op_selector<Element, Element, ElementAccum, TileShape_MNK_PV, GMMA::Major::K, MmaMajorV>(),
120	        AtomLayoutPV{}));
121	
122	    static constexpr int NumMmaThreadsQK = size(TiledMmaQK{});
123	    static constexpr int NumMmaThreads = size(TiledMmaPV{});
124	    static constexpr int NumProducerThreads = !Transpose_V && Use_TMA_KV && Use_TMA_Q ? cutlass::NumThreadsPerWarp : cutlass::NumThreadsPerWarpGroup;
125	    static_assert(NumMmaThreadsQK % cutlass::NumThreadsPerWarpGroup == 0);
126	    static_assert(NumMmaThreads % cutlass::NumThreadsPerWarpGroup == 0);
127	    static constexpr int NumMmaWarpGroups = NumMmaThreads / cutlass::NumThreadsPerWarpGroup;
128	    static_assert(NumMmaWarpGroups == 1 || NumMmaWarpGroups == 2 || NumMmaWarpGroups == 3);
129	
130	    using SmemLayoutAtomQ = decltype(cutlass::gemm::collective::detail::ss_smem_selector<GMMA::Major::K, Element,
131	        decltype(cute::get<0>(TileShape_MNK{})), decltype(cute::get<2>(TileShape_MNK{}))>());
132	    using SmemLayoutQ = decltype(tile_to_shape(SmemLayoutAtomQ{}, select<0, 2>(TileShape_MNK{})));
133	
134	    using SmemLayoutAtomK = decltype(cutlass::gemm::collective::detail::ss_smem_selector<GMMA::Major::K, Element,
135	        decltype(cute::get<1>(TileShape_MNK{})), decltype(cute::get<2>(TileShape_MNK{}))>());
136	    using SmemLayoutK = decltype(tile_to_shape(
137	        SmemLayoutAtomK{},
138	        make_shape(shape<1>(TileShape_MNK{}), shape<2>(TileShape_MNK{}), Int<kStages>{})));
139	
140	    using SmemLayoutAtomVt = decltype(cutlass::gemm::collective::detail::ss_smem_selector<TmaMajorV, Element,
141	                                      Int<kHeadDimV>, decltype(cute::get<2>(TileShape_MNK_PV{}))>());
142	    using SmemLayoutVt = decltype(tile_to_shape(
143	        SmemLayoutAtomVt{},
144	        make_shape(Int<kHeadDimV>{}, shape<2>(TileShape_MNK_PV{}), Int<kStages>{}),
145	        std::conditional_t<TmaMajorV == GMMA::Major::K, cute::Step<_1, _2, _3>, cute::Step<_2, _1, _3>>{}));
146	
147	    using SmemLayoutAtomVtMma = decltype(cutlass::gemm::collective::detail::ss_smem_selector<MmaMajorV, Element,
148	                                         Int<kHeadDimV>, decltype(cute::get<2>(TileShape_MNK_PV{}))>());
149	    using SmemLayoutVtMma = decltype(tile_to_shape(
150	        SmemLayoutAtomVtMma{},
151	        make_shape(Int<kHeadDimV>{}, shape<2>(TileShape_MNK_PV{}), Int<kStages>{}),
152	        std::conditional_t<MmaMajorV == GMMA::Major::K, cute::Step<_1, _2, _3>, cute::Step<_2, _1, _3>>{}));
153	
154	    using SmemLayoutAtomQv = decltype(cutlass::gemm::collective::detail::ss_smem_selector<GMMA::Major::K, Element,
155	        decltype(cute::get<0>(TileShape_MNK_QV{})), decltype(cute::get<2>(TileShape_MNK_QV{}))>());
156	    using SmemLayoutQv = decltype(tile_to_shape(SmemLayoutAtomQv{}, select<0, 2>(TileShape_MNK_QV{})));
157	    using SmemLayoutAtomVMmaQV = decltype(cutlass::gemm::collective::detail::ss_smem_selector<GMMA::Major::K, Element,
158	        decltype(cute::get<1>(TileShape_MNK_QV{})), decltype(cute::get<2>(TileShape_MNK_QV{}))>());
159	    using SmemLayoutVMmaQV = decltype(tile_to_shape(
160	        SmemLayoutAtomVMmaQV{},
161	        make_shape(shape<1>(TileShape_MNK_QV{}), Int<kHeadDimV>{}, Int<kStages>{})));
162	    static_assert(CUTE_STATIC_V(size(SmemLayoutVMmaQV{})) == size(SmemLayoutVtMma{}));
163	
164	    // Only used if we're using cp.async to load V
165	    using SmemLayoutAtomVCpAsync = decltype(cutlass::gemm::collective::detail::ss_smem_selector<GMMA::Major::K, Element,
166	        decltype(cute::get<1>(TileShape_MNK{})), Int<kHeadDimV>>());
167	    using SmemLayoutVCpAsync = decltype(tile_to_shape(
168	        SmemLayoutAtomVCpAsync{},
169	        make_shape(shape<1>(TileShape_MNK{}), Int<kHeadDimV>{}, Int<kStages>{})));
170	
171	    using SmemLayoutAtomP = decltype(cutlass::gemm::collective::detail::ss_smem_selector<GMMA::Major::K, Element,
172	        decltype(cute::get<0>(TileShape_MNK{})), decltype(cute::get<1>(TileShape_MNK{}))>());
173	    using SmemLayoutP = decltype(tile_to_shape(SmemLayoutAtomP{}, select<0, 1>(TileShape_MNK{})));
174	
175	    // Only for LargeHeadDimV where WG0 sends WG1 the scales
176	    using SmemLayoutScale = cute::Layout<cute::Shape<Int<kBlockM>, Int<kStages>>>;
177	
178	    using SmemCopyAtomP = Copy_Atom<cute::SM90_U32x4_STSM_N, Element>;
179	
180	    // Hardcoded to be at most 64 query heads
181	    using SmemLayoutSAux = Layout<Shape<_64>>;
182	
183	    // Use LDSM.T and STSM to transpose V in the case of FP8 and V being row-major.
184	    // For FP16/BF16 we don't do any transposing.
185	    static_assert(!Transpose_V || (kHeadDimV % 32 == 0 && kBlockN % 32 == 0));
186	    static constexpr bool kHeadDimV_multiple_64 = kHeadDimV % 64 == 0;
187	    // Either kHeadDimV is a multiple of 64 (in which case we use a block size of 64 x 32 for the transpose),
188	    // or we need kBlockN to be a multiple of 64 (in which case we use a block size of 32 x 64 for the transpose).
189	    static_assert(!Transpose_V || (kHeadDimV_multiple_64 || kBlockN % 64 == 0));
190	    using LDSM_thread_shape  = std::conditional_t<kHeadDimV_multiple_64, Shape<_32, _4, _1, _1>, Shape<_16, _4, _1, _2>>;
191	    using LDSM_thread_stride = std::conditional_t<kHeadDimV_multiple_64, Stride<_4, _1, _0, _0>, Stride<_4, _1, _0, _64>>;
192	    using LDSM_value_shape = Shape<_2, _2, _1, _4>;
193	    using LDSM_value_stride = Stride<_1, _2, _16, _4>;
194	    using LDSM_divide_shape = std::conditional_t<kHeadDimV_multiple_64, Shape<_64, _8>, Shape<_32, _8>>;
195	    using S2RTiledCopyVt = decltype(make_tiled_copy(
196	        Copy_Atom<SM75_U16x8_LDSM_T, Element>{}, Layout<LDSM_thread_shape, LDSM_thread_stride>{},
197	        Layout<LDSM_value_shape, LDSM_value_stride>{}));
198	
199	    using STSM_thread_shape  = std::conditional_t<kHeadDimV_multiple_64, Shape<_8, _4, _4, _1>, Shape<_8, _4, _2, _2>>;
200	    using STSM_thread_stride = std::conditional_t<kHeadDimV_multiple_64, Stride<_4, _1, _32, _0>, Stride<_4, _1, _32, _64>>;
201	    using STSM_value_shape = Shape<_1, _4, _2, _2>;
202	    using STSM_value_stride = Stride<_0, _1, _4, _8>;
203	    using STSM_divide_shape = Shape<_8, _16>;
204	    // These will not permute the columns of V (the kHeadDimV dimension) but incur bank conflicts
205	    // so a little slower (e.g. 1150 TFLOPS for hdim 256 instead of 1200 TFLOPS).
206	    // Instead we will permute the cols of V, and un-permute the cols of O in the epilogue.
207	    // using STSM_value_shape = Shape<_2, _4, _1, _2>;
208	    // using STSM_value_stride = Stride<_4, _1, _0, _8>;
209	    // using STSM_divide_shape = Shape<_16, _16>;
210	    using R2STiledCopyV = decltype(make_tiled_copy(
211	        Copy_Atom<SM90_U32x4_STSM_N, Element>{}, Layout<STSM_thread_shape, STSM_thread_stride>{},
212	        Layout<STSM_value_shape, STSM_value_stride>{}));
213	
214	    using GmemTiledCopyQ = cute::SM90_TMA_LOAD;
215	    using GmemTiledCopyKV = decltype(cutlass::gemm::collective::detail::sm90_cluster_shape_to_tma_atom(shape<0>(ClusterShape{})));
216	
217	    // We use CpAsync for K and V if PagedKVNonTMA and AppendKV, since TMA doesn't work there
