569	        // If there's tanh softcapping, we do tanh(scores * softmax_scale / softcap_val) * softcap_val.
570	        // Right after this, we multiply by log2(e) before applying exp2.
571	        // To reduce the number of instructions, we instead pre-multiply softmax_scale / softcap_val
572	        // (assigning it to params.softcap_val) and pre-multiply softcap_val * log2(e)
573	        // (assigning it to params.softmax_scale_log2).
574	        return {args.ptr_Q, args.shape_Q, args.stride_Q, shape_Q_packed, stride_Q_packed,
575	                args.ptr_K, args.shape_K, args.stride_K, args.ptr_V, args.headdim_v, args.stride_V,
576	                args.ptr_K_new, args.shape_K_new, args.stride_K_new, args.ptr_V_new, args.stride_V_new,
577	                args.ptr_Qv, args.stride_Qv, shape_Qv_packed, stride_Qv_packed,
578	                args.ptr_rotary_cos, args.shape_rotary, args.stride_rotary_cos,
579	                args.ptr_rotary_sin, args.stride_rotary_sin, args.is_rotary_interleaved,
580	                args.ptr_pagetable, args.shape_pagetable, args.stride_pagetable,
581	                cutlass::FastDivmod(page_size),  // page_size_divmod
582	                cutlass::FastDivmod(!args.ptr_pagetable ? 1 : cute::ceil_div(page_size, kBlockN)),  // blockN_per_page_size_divmod
583	                cutlass::FastDivmod(cute::ceil_div(get<2>(args.shape_Q), get<2>(args.shape_K))),
584	                tma_load_Q, tma_load_K, tma_load_V, tma_load_K_new, tma_load_V_new, tma_load_Qv,
585	                !Has_softcap ? float(args.softmax_scale * M_LOG2E) : float(args.softcap_val * M_LOG2E),
586	                args.ptr_q_descale, args.ptr_k_descale, args.ptr_v_descale,
587	                args.stride_q_descale, args.stride_k_descale, args.stride_v_descale,
588	                !Has_softcap ? 0.f : args.softmax_scale / args.softcap_val,
589	                args.window_size_left, args.window_size_right,
590	                !Split ? 1 : args.num_splits,
591	                args.kv_batch_idx,
592	                args.cu_seqlens_q, args.cu_seqlens_k, args.cu_seqlens_k_new,
593	                args.seqused_q, args.seqused_k, args.leftpad_k, args.seqlens_rotary,
594	                args.ptr_S_aux,
595	                args.cp_world_size, args.cp_rank, args.cp_tot_seqused_k};
596	    }
