598	    /// Issue Tma Descriptor Prefetch -- ideally from a single thread for best performance
599	    CUTLASS_DEVICE
600	    static void prefetch_tma_descriptors(Params const& params) {
601	        if constexpr (Use_TMA_Q) {
602	            cute::prefetch_tma_descriptor(params.tma_load_Q.get_tma_descriptor());
603	            if constexpr (HasQv) {
604	                cute::prefetch_tma_descriptor(params.tma_load_Qv.get_tma_descriptor());
605	            }
606	        }
607	        if constexpr (Use_TMA_KV) {
608	            cute::prefetch_tma_descriptor(params.tma_load_K.get_tma_descriptor());
609	            cute::prefetch_tma_descriptor(params.tma_load_V.get_tma_descriptor());
610	        }
611	        if constexpr (AppendKV) {
612	            cute::prefetch_tma_descriptor(params.tma_load_K_new.get_tma_descriptor());
613	            cute::prefetch_tma_descriptor(params.tma_load_V_new.get_tma_descriptor());
614	        }
615	    }
