931	    template <typename SharedStorage>
932	    CUTLASS_DEVICE void
933	    load_tail(MainloopPipelineK pipeline_k, MainloopPipelineV pipeline_v, MainloopPipelineVt pipeline_vt,
934	              PipelineState& smem_pipe_write, SharedStorage &shared_storage, int const work_idx) {
935	        // If we don't wait for barrier_O here, when using Cluster, CTA0 might exit early and CTA1 will
936	        // try to arrive on barrier_O of CTA0, causing "unspecified launch failure".
937	        shared_storage.pipelines.barrier_O.wait((work_idx + 1) % 2);
938	        int warp_idx_in_warpgroup = __shfl_sync(0xffffffff, (threadIdx.x / 32) % 4, 0);
939	        // Issue the epilogue waits
940	        // TODO: check if this should be called by 1 thread or more
941	        if (warp_idx_in_warpgroup == 0 && cute::elect_one_sync()) {
942	            /* This helps avoid early exit of blocks in Cluster
943	            *  Waits for all stages to either be released (all Consumer UNLOCKs), or if the stage was never used
944	            *  then would just be acquired since the phase was still inverted from make_producer_start_state
945	            */
946	            pipeline_k.producer_tail(smem_pipe_write);
947	            pipeline_v.producer_tail(smem_pipe_write);
948	            if constexpr (Transpose_V) { pipeline_vt.producer_tail(smem_pipe_write); }
949	        }
950	    }
