1003	        SharedStorage& shared_storage
1004	        ) {
1005	        static_assert(is_rmem<FrgTensorO>::value, "O tensor must be rmem resident.");
1006	        static constexpr int kBlockM = get<0>(TileShape_MNK{});
1007	        static constexpr int kBlockN = get<1>(TileShape_MNK{});
1008	
1009	        // can't use auto [m_block, ...] = block_coord since structured binding cannot be captured in lambda
1010	        int const m_block = get<0>(block_coord);
1011	        int const bidh = get<1>(block_coord);
1012	        int const bidb = get<2>(block_coord);
1013	        int const split_idx = get<3>(block_coord);
1014	        int const bidh_kv = !PackGQA ? params.qhead_per_khead_divmod.divide(bidh) : bidh;
1015	        auto [n_block_min, n_block_max, n_offset] = BlockMN_t::get_n_block_min_max(
1016	            seqlen_info, m_block, bidb, split_idx, params.num_splits,
1017	            params.window_size_left, params.window_size_right, params.qhead_per_khead_divmod);
1018	        // It's possible to have n_block_max <= n_block_min. We don't want to load Q or change any barrier
1019	        if constexpr (Is_causal || Is_local || Varlen || Split) {
1020	            if (n_block_max <= n_block_min) { return false; }
1021	        }
1022	
1023	        Tensor sQ = make_tensor(make_smem_ptr(shared_storage.tensors.mainloop.smem_q.data()), SmemLayoutQ{});
1024	        Tensor sK = make_tensor(make_smem_ptr(shared_storage.tensors.mainloop.smem_k.data()), SmemLayoutK{});
1025	        Tensor sV = make_tensor(make_smem_ptr(shared_storage.tensors.mainloop.smem_v.data()), SmemLayoutVtMma{});
1026	        Tensor sP = [&] {
1027	            if constexpr (MmaPV_is_RS) {
1028	                // We might not have smem_p if !MmaPV_is_RS, just use smem_q as a placeholder since we don't use it
1029	                return make_tensor(make_smem_ptr(shared_storage.tensors.mainloop.smem_q.data()), SmemLayoutP{});
1030	            } else {
1031	                return make_tensor(make_smem_ptr(shared_storage.tensors.mainloop.smem_p.data()), SmemLayoutP{});
1032	            }
1033	        }();
1034	        Tensor sScale = [&] {
1035	            if constexpr (LargeHeadDimV) {
1036	                return make_tensor(make_smem_ptr(shared_storage.tensors.mainloop.smem_scale.data()), SmemLayoutScale{});
1037	            } else { // won't be used, just a placeholder
1038	                return make_tensor(make_smem_ptr(static_cast<float*>(nullptr)), SmemLayoutScale{});
1039	            }
1040	        }();
1041	        Tensor sQv = make_tensor(make_smem_ptr(shared_storage.tensors.mainloop.smem_qv.data()), SmemLayoutQv{});
1042	        Tensor sVMmaQV = make_tensor(make_smem_ptr(shared_storage.tensors.mainloop.smem_v.data()), SmemLayoutVMmaQV{});
1043	
1044	        if constexpr (!MmaQK_is_RS) {
1045	            static_assert(stride<0>(typename TiledMmaQK::ALayout{}) == 0 and
1046	                        stride<0>(typename TiledMmaQK::BLayout{}) == 0 and
1047	                        size<0>(typename TiledMmaQK::ALayout{}) == cutlass::NumThreadsPerWarpGroup and
1048	                        size<0>(typename TiledMmaQK::BLayout{}) == cutlass::NumThreadsPerWarpGroup,
1049	                "Stride of the first mode must be 0 and the size of the mode must be NumThreadsPerWarpGroup");
